{
  "name": "FPGA时序发生器模块",
  "name_en": "FPGA Sequencer Generator Module",
  "manufacturer": "",
  "description": "一种面向FPGA时序发生模块的硬件控制接口，用于在实验控制或数据采集中配置并启动可编程序列。可设置序列长度、等待时间、时钟分频、重复参数、外部启动与嵌套循环参数，并向板载存储器写入时序数据后执行输出。",
  "description_en": "A hardware control interface for an FPGA sequencer generator module, used to configure and run programmable timing sequences in laboratory control or data acquisition setups. It supports sequence length, wait time, clock division, repeat settings, external start, nested loop parameters, and writing sequence data into onboard memory for execution.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化时序发生模块",
      "description_en": "initialize the sequencer module"
    },
    {
      "action_name": "auto-reset",
      "description": "复位时序发生模块",
      "description_en": "reset the sequencer module"
    },
    {
      "action_name": "auto-start",
      "description": "启动序列输出",
      "description_en": "start sequence generation"
    },
    {
      "action_name": "auto-set_size",
      "description": "设置序列长度",
      "description_en": "set sequence length"
    },
    {
      "action_name": "auto-set_wait",
      "description": "设置等待时间",
      "description_en": "set wait time"
    },
    {
      "action_name": "auto-set_clk_divide",
      "description": "设置时钟分频",
      "description_en": "set clock divide factor"
    },
    {
      "action_name": "auto-set_repeat_start",
      "description": "设置重复起始位置",
      "description_en": "set repeat start position"
    },
    {
      "action_name": "auto-set_repeat",
      "description": "设置重复次数",
      "description_en": "set repeat count"
    },
    {
      "action_name": "auto-is_done",
      "description": "检查序列是否完成",
      "description_en": "check whether sequence execution is done"
    },
    {
      "action_name": "auto-set_en_ext_start",
      "description": "设置是否启用外部启动",
      "description_en": "set whether external start is enabled"
    },
    {
      "action_name": "auto-set_nested_start",
      "description": "设置嵌套循环起始位置",
      "description_en": "set nested loop start position"
    },
    {
      "action_name": "auto-set_nested_stop",
      "description": "设置嵌套循环结束位置",
      "description_en": "set nested loop stop position"
    },
    {
      "action_name": "auto-set_nested_repeat",
      "description": "设置嵌套循环重复次数",
      "description_en": "set nested loop repeat count"
    },
    {
      "action_name": "auto-set_data",
      "description": "写入序列数据到存储器",
      "description_en": "write sequence data to memory"
    }
  ],
  "tag_hints": [
    "FPGA sequencer",
    "timing sequence generation",
    "programmable pulse sequence",
    "external trigger start",
    "nested repeat loop",
    "clock division",
    "sequence memory"
  ]
}

